-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.readings (
  user_id uuid default auth.uid() not null,
  note_id text not null,
  anchor text,
  progress real default 0 not null,
  updated_at timestamp with time zone default now() not null,
  constraint readings_pkey PRIMARY KEY (user_id, note_id),
  constraint readings_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint readings_anchor_check CHECK ((length(anchor) <= 200)),
  constraint readings_note_id_check CHECK ((note_id ~ '^AP-[A-Z0-9]+(-[A-Z0-9]+)+$'::text)),
  constraint readings_progress_check CHECK (((progress >= (0)::double precision) AND (progress <= (1)::double precision)))
);

CREATE INDEX readings_recent ON public.readings USING btree (user_id, updated_at DESC);

CREATE TRIGGER progress_never_decreases BEFORE UPDATE ON public.readings FOR EACH ROW EXECUTE FUNCTION public.readings_progress_never_decreases();
CREATE TRIGGER quota_rows AFTER INSERT ON public.readings FOR EACH ROW EXECUTE FUNCTION public.quota_rows('2000');

alter table public.readings enable row level security;

create policy "delete own readings" on public.readings
  as permissive
  for delete
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

create policy "insert own readings" on public.readings
  as permissive
  for insert
  to authenticated
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

create policy "read own readings" on public.readings
  as permissive
  for select
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

create policy "update own readings" on public.readings
  as permissive
  for update
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check ((user_id = ( SELECT auth.uid() AS uid)));

grant delete, insert, select, update on table public.readings to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.readings to service_role;
